import FamilyControls

@main
struct opalcloneApp: App {
    @AppStorage("hasCompletedPremiumOnboarding") private var hasCompletedOnboarding = false
    @AppStorage("isPremium") private var isPremium = false
    @State private var showOnboarding = false

    let sharedModelContainer: ModelContainer
    @StateObject private var viewModelContainer: ViewModelContainer

    init() {
        // Initialize ModelContainer once
        let container = ModelContainer.production
        self.sharedModelContainer = container

        // Initialize ViewModelContainer with model context
        let viewModelContainer = ViewModelContainer(modelContext: container.mainContext)
        _viewModelContainer = StateObject(wrappedValue: viewModelContainer)

        // Request notification permissions
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { granted, error in
            if granted {
                #if DEBUG
                print("Notifications authorized")
                #endif
            }
        }

        // Don't request Family Controls here - let onboarding handle it
    }

    var body: some Scene {
        WindowGroup {
            // Allow testing without premium in DEBUG mode
            #if DEBUG
            if hasCompletedOnboarding || isPremium {
                MainTabView()
                    .environmentObject(viewModelContainer)
            } else {
                PremiumOnboardingView()
                    .environmentObject(viewModelContainer)
            }
            #else
            // Production: require both onboarding and premium
            if hasCompletedOnboarding && isPremium {
                MainTabView()
                    .environmentObject(viewModelContainer)
            } else {
                PremiumOnboardingView()
                    .environmentObject(viewModelContainer)
            }
            #endif
        }
        .modelContainer(sharedModelContainer)
        .environment(\.modelContext, sharedModelContainer.mainContext)
    }
