@Model
final class FocusSession {
    @Attribute(.unique) var id: UUID = UUID()
    var startTime: Date
    var endTime: Date?
    var duration: Int // in minutes
    var completed: Bool
    var difficultyRawValue: String // Store enum as string

    var difficulty: DifficultyLevel {
        get { DifficultyLevel(rawValue: difficultyRawValue) ?? .normal }
        set { difficultyRawValue = newValue.rawValue }
    }

    init(startTime: Date = Date(), duration: Int, difficulty: DifficultyLevel = .normal) {
        self.id = UUID()
        self.startTime = startTime
        self.duration = duration
        self.difficultyRawValue = difficulty.rawValue
        self.completed = false
        self.endTime = nil
    }
}

enum DifficultyLevel: String, Codable, CaseIterable {
    case easy = "Easy"
    case normal = "Normal"
    case hard = "Hard"

    var config: DifficultyConfig {
        switch self {
        case .easy:
            return DifficultyConfig(canPause: true, canEnd: true, delays: 0)
        case .normal:
            return DifficultyConfig(canPause: true, canEnd: false, delays: 10)
        case .hard:
            return DifficultyConfig(canPause: false, canEnd: false, delays: 30)
        }
    }
}

struct DifficultyConfig {
    let canPause: Bool
    let canEnd: Bool
    let delays: Int
