import UserNotifications

@main
struct OffleafApp: App {
    @AppStorage("hasCompletedOnboarding") private var hasCompletedOnboarding = false
    @StateObject private var notificationManager = NotificationManager.shared

    init() {
        setupNotifications()
    }

    var sharedModelContainer: ModelContainer = {
        let schema = Schema([
            Item.self,
        ])
        let modelConfiguration = ModelConfiguration(schema: schema, isStoredInMemoryOnly: false)

        do {
            return try ModelContainer(for: schema, configurations: [modelConfiguration])
        } catch {
            fatalError("Could not create ModelContainer: \(error)")
        }
    }()

    var body: some Scene {
        WindowGroup {
            Group {
                if hasCompletedOnboarding {
                    ContentView()
                } else {
                    SplashScreenView()
                }
            }
            .onAppear {
                // Check for missed milestones when app launches
                notificationManager.checkAndRescheduleMissedMilestones()
            }
        }
        .modelContainer(sharedModelContainer)
    }

    private func setupNotifications() {
        UNUserNotificationCenter.current().delegate = NotificationManager.shared

        // Define notification actions
        let checkInAction = UNNotificationAction(
            identifier: "CHECK_IN_ACTION",
            title: "Check In Now",
            options: [.foreground]
        )

        let snoozeAction = UNNotificationAction(
            identifier: "SNOOZE_ACTION",
            title: "Remind in 1 Hour",
            options: []
        )

        // Create categories
        let checkInCategory = UNNotificationCategory(
            identifier: "DAILY_CHECKIN",
            actions: [checkInAction, snoozeAction],
            intentIdentifiers: [],
            options: []
        )

        let milestoneCategory = UNNotificationCategory(
            identifier: "MILESTONE",
            actions: [],
            intentIdentifiers: [],
            options: [.customDismissAction]
        )

        // Register categories
        UNUserNotificationCenter.current().setNotificationCategories([
            checkInCategory,
            milestoneCategory
        ])
    }
}
